<?php
declare(strict_types=1);
require_once __DIR__.'/helpers.php';
function confirm_online_order(int $orderId,string $paymentReference): void {
    $db=get_db();$order=$db->prepare('SELECT * FROM orders WHERE id=:id FOR UPDATE');$order->execute(['id'=>$orderId]);$row=$order->fetch();if(!$row)throw new RuntimeException('Order not found.');if($row['payment_status']==='paid')return;if($row['payment_status']!=='pending')throw new RuntimeException('Order is not awaiting payment.');$reservations=$db->prepare('SELECT r.* FROM inventory_reservations r WHERE r.quote_id=:quote AND r.status="reserved" FOR UPDATE');$reservations->execute(['quote'=>$row['checkout_quote_id']]);$reserved=$reservations->fetchAll();if(!$reserved)throw new RuntimeException('Order stock reservation expired.');foreach($reserved as $reservation){$update=$db->prepare('UPDATE inventory_levels SET stock_quantity=stock_quantity-:qty_sale,reserved_quantity=reserved_quantity-:qty_reserve,updated_at=UTC_TIMESTAMP() WHERE variant_id=:variant AND stock_quantity>=:qty_stock AND reserved_quantity>=:qty_reserved');$update->execute(['qty_sale'=>$reservation['quantity'],'qty_reserve'=>$reservation['quantity'],'qty_stock'=>$reservation['quantity'],'qty_reserved'=>$reservation['quantity'],'variant'=>$reservation['variant_id']]);if(!$update->rowCount())throw new RuntimeException('Reserved stock cannot be converted.');$db->prepare('UPDATE inventory_reservations SET status="converted",released_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$reservation['id']]);}$items=$db->prepare('SELECT oi.id,oi.vendor_id,oi.variant_id,oi.quantity,f.vendor_net_amount FROM order_items oi JOIN order_item_financials f ON f.order_item_id=oi.id WHERE oi.order_id=:order');$items->execute(['order'=>$orderId]);foreach($items->fetchAll() as $item){$level=$db->prepare('SELECT stock_quantity,reserved_quantity FROM inventory_levels WHERE variant_id=:variant');$level->execute(['variant'=>$item['variant_id']]);$after=$level->fetch();$db->prepare('INSERT INTO inventory_movements (variant_id,vendor_id,movement_type,quantity_delta,reserved_delta,stock_after,reserved_after,reference_type,reference_id,note,actor_type,actor_id,created_at) VALUES (:variant_move,:vendor,"sale",-:qty_move,-:qty_reserved,:stock,:reserved,"order_item",:reference,"Online payment confirmed","system",:system,UTC_TIMESTAMP())')->execute(['variant_move'=>$item['variant_id'],'vendor'=>$item['vendor_id'],'qty_move'=>$item['quantity'],'qty_reserved'=>$item['quantity'],'stock'=>$after['stock_quantity'],'reserved'=>$after['reserved_quantity'],'reference'=>(string)$item['id'],'system'=>'00000000-0000-0000-0000-000000000000']);$db->prepare('INSERT INTO vendor_ledger_entries (id,vendor_id,entry_type,amount,currency,balance_bucket,reference_type,reference_id,description,available_at,created_at) VALUES (:id,:vendor,"order_earning",:amount,"INR","pending","order_item",:reference,"Order earning pending delivery",DATE_ADD(UTC_TIMESTAMP(),INTERVAL 7 DAY),UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'vendor'=>$item['vendor_id'],'amount'=>$item['vendor_net_amount'],'reference'=>(string)$item['id']]);}$db->prepare('UPDATE orders SET status="confirmed",payment_status="paid",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$orderId]);$db->prepare('UPDATE payment_attempts SET status="paid",provider_payment_id=:reference,updated_at=UTC_TIMESTAMP() WHERE order_id=:order AND status="created"')->execute(['reference'=>$paymentReference,'order'=>$orderId]);record_status_change('order',(string)$orderId,$row['status'],'confirmed','Online payment confirmed');
}
function fail_online_order(int $orderId,string $message): void {$db=get_db();$stmt=$db->prepare('SELECT * FROM orders WHERE id=:id FOR UPDATE');$stmt->execute(['id'=>$orderId]);$order=$stmt->fetch();if(!$order||$order['payment_status']!=='pending')return;release_quote_reservations($order['checkout_quote_id']);$db->prepare('UPDATE orders SET status="payment_failed",payment_status="failed",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$orderId]);$db->prepare('UPDATE payment_attempts SET status="failed",failure_message=:message,updated_at=UTC_TIMESTAMP() WHERE order_id=:order AND status="created"')->execute(['message'=>mb_substr($message,0,500),'order'=>$orderId]);record_status_change('order',(string)$orderId,$order['status'],'payment_failed',$message);}
